    init {
        // PathData ਨੂੰ Path ਵਿੱਚ ਬਦਲੋ
        vectorPath.set(PathParser.createPathFromPathData(pathString))
        startAnimation()
    }

    private fun startAnimation() {
        ValueAnimator.ofFloat(0f, 1f).apply {
            duration = 3000
            interpolator = DecelerateInterpolator()
            addUpdateListener {
                progress = it.animatedValue as Float
                invalidate()
            }
            start()
        }
    }

    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)

        // ਸਕੇਲਿੰਗ ਤਾਂ ਜੋ ਪੂਰਾ ਵਿਊ ਕਵਰ ਹੋਵੇ
        val scaleX = width.toFloat() / 337f
        val scaleY = height.toFloat() / 150f
        canvas.scale(scaleX, scaleY)

        val pathMeasure = android.graphics.PathMeasure(vectorPath, false)
        val length = pathMeasure.length
        val effect = android.graphics.DashPathEffect(floatArrayOf(length, length), (1f - progress) * length)
        paint.pathEffect = effect

        canvas.drawPath(vectorPath, paint)
    }
}
